using System;using System.Collections.Generic;using System.IO;using System.Net;using System.Net.Sockets;using System.Text;using System.Text.RegularExpressions;using System.Threading;using System.Web.Script.Serialization;
// Small directory for 2019 player-hosted rooms. Game traffic stays peer-to-peer.
internal static class DirectoryServer {
 sealed class Room { internal string Id,Secret,Address,Advert,Account;internal DateTime Seen; }
 static readonly Dictionary<string,Room> rooms=new Dictionary<string,Room>(StringComparer.Ordinal);static readonly object gate=new object();static readonly SemaphoreSlim slots=new SemaphoreSlim(64,64);static JavaScriptSerializer Json(){return new JavaScriptSerializer{MaxJsonLength=262144};}static Uri auth=new Uri("http://217.199.220.41:3001/");static TcpListener listener;static IPAddress localAdvertise;static bool trustLoopbackProxy;const int ttl=30;
 static string Str(IDictionary<string,object> o,string key){object value;return o!=null&&o.TryGetValue(key,out value)&&value!=null?Convert.ToString(value):"";}
 static bool Hex(string x,int length){return x!=null&&x.Length==length&&Regex.IsMatch(x,"\\A[0-9a-f]+\\z");}
 static bool Equal(string a,string b){if(a==null||b==null||a.Length!=b.Length)return false;int diff=0;for(int i=0;i<a.Length;i++)diff|=a[i]^b[i];return diff==0;}
 static void Prune(){var expired=new List<string>();foreach(var p in rooms)if((DateTime.UtcNow-p.Value.Seen).TotalSeconds>ttl)expired.Add(p.Key);foreach(string key in expired)rooms.Remove(key);}
 static bool ValidAdvert(string value){try{byte[] bytes=Convert.FromBase64String(value);if(bytes.Length>512)return false;string[] p=new UTF8Encoding(false,true).GetString(bytes).Split('|');if(!((p.Length==14&&p[0]=="PUBG2019LAN2")||((p.Length==15||p.Length==16)&&p[0]=="PUBG2019LAN3")))return false;string name=new UTF8Encoding(false,true).GetString(Convert.FromBase64String(p[1]));int team,port,capacity,bots,players,min,lobby;if(String.IsNullOrWhiteSpace(name)||name.Length>32||Regex.IsMatch(name,@"[\p{C}]"))return false;if(Array.IndexOf(new[]{"Miramar","Erangel","ErangelClassic","Sanhok","Vikendi","Training"},p[2])<0||!Int32.TryParse(p[3],out team)||(team!=1&&team!=2&&team!=4)||(p[4]!="TPP"&&p[4]!="FPP")||!Int32.TryParse(p[5],out port)||(p.Length==14?port!=8888:(port<8000||port>10000))||(p[6]!="0"&&p[6]!="1")||(p[7]!="0"&&p[7]!="1"))return false;if(p.Length>=15&&(!Int32.TryParse(p[14],out lobby)||lobby!=port))return false;if(p.Length==16&&p[15]!="0"&&p[15]!="1")return false;if(!Int32.TryParse(p[8],out capacity)||!Int32.TryParse(p[9],out bots)||!Int32.TryParse(p[10],out players)||!Int32.TryParse(p[11],out min)||capacity<1||capacity>100||bots<0||bots>95||bots>capacity||players<0||players>capacity-bots||min<1||min>capacity||(p[12]!="0"&&p[12]!="1")||!Regex.IsMatch(p[13],@"^PUBG-[A-F0-9]{8}$"))return false;return true;}catch(Exception){return false;}}
 static string VerifyAccount(string cookie,string bearer){if((String.IsNullOrEmpty(cookie)&&String.IsNullOrEmpty(bearer))||cookie.Length>4096||bearer.Length>4096||cookie.IndexOfAny(new[]{'\r','\n'})>=0||bearer.IndexOfAny(new[]{'\r','\n'})>=0)return null;try{var req=(HttpWebRequest)WebRequest.Create(new Uri(auth,"/api/auth/me"));req.Method="GET";req.Accept="application/json";if(!String.IsNullOrEmpty(bearer))req.Headers[HttpRequestHeader.Authorization]="Bearer "+bearer;else req.Headers[HttpRequestHeader.Cookie]=cookie;req.Timeout=6000;req.ReadWriteTimeout=6000;req.AllowAutoRedirect=false;using(var res=(HttpWebResponse)req.GetResponse())using(var reader=new StreamReader(res.GetResponseStream(),Encoding.UTF8)){if(res.StatusCode!=HttpStatusCode.OK)return null;string body=reader.ReadToEnd();if(body.Length>65536)return null;var obj=Json().DeserializeObject(body) as IDictionary<string,object>;object v;var user=obj!=null&&obj.TryGetValue("user",out v)?v as IDictionary<string,object>:null;var session=obj!=null&&obj.TryGetValue("session",out v)?v as IDictionary<string,object>:null;string id=Str(session,"accountGuid");if(id=="")id=Str(session,"AccountGuid");string name=Str(user,"username");if(id.Length<1||id.Length>128||!Regex.IsMatch(name,@"^[A-Za-z0-9_-]{1,24}$"))return null;return id;}}catch(Exception){return null;}}
 static bool IsLocal(IPAddress ip){byte[] b=ip.GetAddressBytes();return IPAddress.IsLoopback(ip)||b[0]==10||(b[0]==172&&b[1]>=16&&b[1]<=31)||(b[0]==192&&b[1]==168);}
 static object Process(string method,string path,string payload,IPAddress remote,out int status){status=200;if(method=="GET"&&path=="/health")return new{ok=true};if(method=="GET"&&path=="/rooms"){lock(gate){Prune();var list=new List<object>();foreach(var r in rooms.Values)list.Add(new{ip=r.Address,advert=r.Advert});return new{rooms=list.ToArray()};}}
 if(method!="POST"||(path!="/publish"&&path!="/remove")){status=404;return new{error="Not found"};}IDictionary<string,object> input;try{input=Json().DeserializeObject(payload) as IDictionary<string,object>;}catch(Exception){status=400;return new{error="Invalid JSON"};}string id=Str(input,"id"),secret=Str(input,"secret");if(!Hex(id,32)||!Hex(secret,64)){status=400;return new{error="Invalid room lease"};}
 if(path=="/remove"){lock(gate){Room found;if(rooms.TryGetValue(id,out found)&&Equal(found.Secret,secret))rooms.Remove(id);}return new{ok=true};}
 string advert=Str(input,"advert"),cookie=Str(input,"cookie"),bearer=Str(input,"bearer");if(!ValidAdvert(advert)){status=400;return new{error="Invalid room details"};}string account=VerifyAccount(cookie,bearer);if(account==null){status=401;return new{error="Account verification failed"};}
 lock(gate){Prune();Room existing;if(rooms.TryGetValue(id,out existing)){if(!Equal(existing.Secret,secret)||existing.Account!=account){status=403;return new{error="Room lease rejected"};}}else{if(rooms.Count>=256){status=503;return new{error="Directory is full"};}existing=new Room{Id=id,Secret=secret,Account=account};rooms.Add(id,existing);}existing.Address=(localAdvertise!=null&&IsLocal(remote)?localAdvertise:remote).ToString();existing.Advert=advert;existing.Seen=DateTime.UtcNow;}return new{ok=true};}
 static void Handle(object state){using(var client=(TcpClient)state){try{client.ReceiveTimeout=8000;client.SendTimeout=8000;using(var stream=client.GetStream()){var header=new MemoryStream();int c;while((c=stream.ReadByte())>=0){header.WriteByte((byte)c);int n=(int)header.Length;var b=header.GetBuffer();if(n>=4&&b[n-4]==13&&b[n-3]==10&&b[n-2]==13&&b[n-1]==10)break;if(n>16384)throw new InvalidDataException();}string[] lines=Encoding.ASCII.GetString(header.ToArray()).Split(new[]{"\r\n"},StringSplitOptions.None);string[] first=lines[0].Split(' ');if(first.Length!=3)return;int length=0;foreach(string line in lines)if(line.StartsWith("Content-Length:",StringComparison.OrdinalIgnoreCase)&&!Int32.TryParse(line.Substring(15).Trim(),out length))return;if(length<0||length>8192)return;byte[] bytes=new byte[length];for(int pos=0;pos<length;){int n=stream.Read(bytes,pos,length-pos);if(n<=0)return;pos+=n;}IPAddress source=((IPEndPoint)client.Client.RemoteEndPoint).Address;
 if(trustLoopbackProxy&&IPAddress.IsLoopback(source)){string forwarded=null;foreach(string line in lines)if(line.StartsWith("X-PUBG-Client-IP:",StringComparison.OrdinalIgnoreCase)){if(forwarded!=null)throw new InvalidDataException("Duplicate proxy address");forwarded=line.Substring(17).Trim();}if(forwarded!=null){IPAddress parsed;if(!IPAddress.TryParse(forwarded,out parsed)||parsed.AddressFamily!=AddressFamily.InterNetwork||IPAddress.IsLoopback(parsed))throw new InvalidDataException("Invalid proxy address");source=parsed;}}
 int status;object result=Process(first[0],first[1],Encoding.UTF8.GetString(bytes),source,out status);byte[] body=Encoding.UTF8.GetBytes(Json().Serialize(result));string code=status==200?"OK":status==400?"Bad Request":status==401?"Unauthorized":status==403?"Forbidden":status==404?"Not Found":"Unavailable";byte[] head=Encoding.ASCII.GetBytes("HTTP/1.1 "+status+" "+code+"\r\nContent-Type: application/json; charset=utf-8\r\nCache-Control: no-store\r\nConnection: close\r\nContent-Length: "+body.Length+"\r\n\r\n");stream.Write(head,0,head.Length);stream.Write(body,0,body.Length);}}catch(Exception){}finally{slots.Release();}}}
 static int Main(string[] args){try{IPAddress bind=IPAddress.Loopback;int port=18900;for(int i=0;i<args.Length;i++){if(args[i]=="--trust-loopback-proxy")trustLoopbackProxy=true;else if(args[i]=="--bind"&&i+1<args.Length)bind=IPAddress.Parse(args[++i]);else if(args[i]=="--port"&&i+1<args.Length)port=Int32.Parse(args[++i]);else if(args[i]=="--auth-url"&&i+1<args.Length)auth=new Uri(args[++i]);else if(args[i]=="--local-advertise"&&i+1<args.Length)localAdvertise=IPAddress.Parse(args[++i]);else throw new ArgumentException("Usage: PUBG2019NetDirectory.exe [--bind 127.0.0.1|0.0.0.0] [--port 18900] [--auth-url URL] [--local-advertise PUBLIC_IPV4]");}if((trustLoopbackProxy&&!IPAddress.IsLoopback(bind))||bind.AddressFamily!=AddressFamily.InterNetwork||port<1||port>65535||(auth.Scheme!="http"&&auth.Scheme!="https")||(localAdvertise!=null&&(localAdvertise.AddressFamily!=AddressFamily.InterNetwork||IsLocal(localAdvertise)||localAdvertise.GetAddressBytes()[0]<1||localAdvertise.GetAddressBytes()[0]>=224)))throw new ArgumentException("Invalid address.");listener=new TcpListener(bind,port);listener.Start(128);Console.WriteLine("PUBG 2019 directory listening on "+bind+":"+port+" (room expiry "+ttl+" seconds)");while(true){var c=listener.AcceptTcpClient();if(!slots.Wait(0)){c.Close();continue;}ThreadPool.QueueUserWorkItem(Handle,c);}}catch(Exception e){Console.Error.WriteLine(e.Message);return 1;}}
}
